    office(key, ctx) { const arr = key.split(".").reduce((o, k) => o && o[k], OFFICE); return arr ? U.fill(officePick(key, arr), ctx || {}) : ""; },
    msg(key, ctx) { const s = pickFresh("m:" + key, MSG[key]); return s ? U.fill(s, ctx) : null; },
