      const s = pickFresh("b:" + (own || key) + (civ ? ":c" : ""), civ ? BUBBLE_CIVILIAN[key] : BUBBLE[own || key]);
      if (!s) return null;
      return U.fill(s, Object.assign({}, ctx, { item: ITEM[ctx.item] || ctx.item }));
